<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { Graph, Shape } from '@antv/x6'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Search } from '@element-plus/icons-vue'
import { useRoute, useRouter } from 'vue-router'
import {
  developmentApi, integrationApi, operationsApi, releaseApi, workflowApi,
  type DevFile, type DevelopmentSchedule, type DevelopmentWorkflowDefinition, type ProjectWorkflowDefinition,
  type ProjectImpactView, type ProjectRerunBatch, type IntegrationTask, type IntegrationTaskSchedule, type ScheduleConfig,
  type WorkflowNode, type WorkflowView
} from '../../api/domain'
import { productNavigation } from '../../navigation'
import { formatDateTime, statusLabel as commonStatusLabel } from '../../utils/display'
import { dataSourceApi, type DataSourceView } from '../../api/platform'

type NodeKind='SQL'|'PYTHON'|'SHELL'|'SEATUNNEL'|'CONDITION'
type TaskFilter='ALL'|'SQL'|'PYTHON'|'SHELL'
type InspectorTab='prop'|'schedule'|'dep'
type SourceFilter='ALL'|'PROJECT'|'DEVELOPMENT'|'CUSTOM'
type NodeData={
  name:string;nodeType:NodeKind;devFileId?:number;integrationTaskId?:number;configJson:string;
  taskVersion?:number;lifecycleStatus?:string;ownerName?:string;selected?:boolean;focus?:boolean;
  runtimeStatus?:string;plannedAt?:string;finishedAt?:string;nextPlannedAt?:string;errorMessage?:string
}
type ListRow={
  key:string;source:'PROJECT'|'DEVELOPMENT'|'CUSTOM';name:string;code:string;status:string;version:string;
  schedule:string;upstreamCount:number;downstreamCount:number;runtimeStatus?:string;nextPlannedAt?:string;
  updatedAt?:string;project?:ProjectWorkflowDefinition;dev?:DevelopmentWorkflowDefinition;workflow?:WorkflowView
}

const route=useRoute(),router=useRouter()
const loading=ref(true),rows=ref<WorkflowView[]>([]),devDefinitions=ref<DevelopmentWorkflowDefinition[]>([]),projectDefinitions=ref<ProjectWorkflowDefinition[]>([])
const editorOpen=ref(false),developmentMode=ref(false),projectMode=ref(false),focusFileId=ref<number>(),saving=ref(false),dirty=ref(false),editorNavOpen=ref(false)
const current=ref<WorkflowView|null>(null),currentDev=ref<DevelopmentWorkflowDefinition>(),currentProject=ref<ProjectWorkflowDefinition>(),files=ref<DevFile[]>([]),integrationTasks=ref<IntegrationTask[]>([]),scheduleSources=ref<DataSourceView[]>([])
const focusSchedule=ref<DevelopmentSchedule>(),workflowSchedule=ref<ScheduleConfig>()
const selectedCode=ref(''),selectedEdgeId=ref(''),selectedSchedule=ref<DevelopmentSchedule>(),selectedIntegrationSchedule=ref<IntegrationTaskSchedule>()
const listSearch=ref(''),sourceFilter=ref<SourceFilter>('ALL'),statusFilter=ref('ALL'),taskSearch=ref(''),taskFilter=ref<TaskFilter>('ALL'),inspectorTab=ref<InspectorTab>('prop')
const canvasRef=ref<HTMLDivElement>(),graphScale=ref(1),graphRevision=ref(0)
const form=reactive({name:'',description:''}),nodeDraft=reactive<NodeData>({name:'',nodeType:'SQL',configJson:'{}'}),conditionExpression=ref("status == 'SUCCESS'")
const scheduleDraft=reactive({enabled:false,cycleType:'DAILY',executionTime:'02:00',cronExpression:'0 0 2 * * ?',timezone:'Asia/Shanghai',dataSourceId:undefined as number|undefined,databaseName:'',bizDateParam:'${system.biz.date-1}',retryTimes:3,retryIntervalMinutes:5,timeoutMinutes:120})
const stats=reactive({nodes:0,edges:0,roots:0,leaves:0})
const impactOpen=ref(false),impactLoading=ref(false),impactView=ref<ProjectImpactView>(),rerunBatch=ref<ProjectRerunBatch>()
const impactIncludeSource=ref(false),impactBusinessDate=ref(new Date().toISOString().slice(0,10))
let graph:Graph|undefined
let runtimeTimer:number|undefined
let rerunTimer:number|undefined

function stripExt(v:string){return (v||'').replace(/\.(sql|sh|py)$/i,'')}
function msg(e:unknown){return e instanceof Error?e.message:'操作失败'}
function fmt(v?:string){return formatDateTime(v)}
function typeLabel(v?:string){return ({SQL:'SQL',PYTHON:'Python',SHELL:'Shell',SEATUNNEL:'SeaTunnel',CONDITION:'条件'} as Record<string,string>)[v||'']||v||'任务'}
function lifecycleLabel(v?:string){return v==='ONLINE'?'已上线':'未上线'}
function cycleLabel(v?:string){return ({DAILY:'每日',HOURLY:'每小时',WEEKLY:'每周',MONTHLY:'每月',CRON:'Cron'} as Record<string,string>)[v||'']||v||'—'}
function scheduleLabel(row:DevelopmentWorkflowDefinition){if(!row.scheduleEnabled)return'未启用';return row.cycleType==='CRON'?(row.cronExpression||'Cron'):`${cycleLabel(row.cycleType)} ${row.executionTime||''}`.trim()}
function runtimeLabel(v?:string){const s=(v||'').toUpperCase();if(s==='WAITING_DEPENDENCY')return'等待依赖';return commonStatusLabel(s||'READY')}
function runtimeClass(v?:string){const s=(v||'').toUpperCase();if(s==='WAITING_DEPENDENCY')return'waiting';if(/RUNNING|STARTING|QUEUED|SUBMITTED/.test(s))return'running';if(/SUCCESS|FINISHED|COMPLETED/.test(s))return'success';if(/FAIL|ERROR/.test(s))return'failed';if(/CANCEL|STOP|KILL/.test(s))return'stopped';return'idle'}
function integrationRoute(t?:IntegrationTask){const x=t?.tables?.[0];return x?`${x.sourceDatabase}.${x.sourceTable} → ${x.targetDatabase}.${x.targetTable}`:(t?`${t.sourceType} → ${t.targetType}`:'未绑定离线同步任务')}
function integrationMode(t?:IntegrationTask){return ({FULL:'全量',INCREMENTAL:'增量',FULL_INCREMENTAL:'全量 + 增量'} as Record<string,string>)[t?.syncMode||'']||t?.syncMode||'—'}
function parseConfig(v?:string){try{return JSON.parse(v||'{}') as Record<string,unknown>}catch{return {}}}
function integrationId(v?:string){const n=Number(parseConfig(v).integrationTaskId||0);return n>0?n:undefined}

const definitionRows=computed<ListRow[]>(()=>{
  const projects=projectDefinitions.value.map(p=>({key:`project-${p.projectId}`,source:'PROJECT' as const,name:p.name,code:`project_${p.projectId}`,status:p.failedTasks>0?'FAILED':p.runningTasks>0?'RUNNING':'READY',version:`${p.taskCount}任务`,schedule:`${p.enabledSchedules} 已启用`,upstreamCount:0,downstreamCount:0,runtimeStatus:p.failedTasks>0?'FAILED':p.runningTasks>0?'RUNNING':'READY',project:p}))
  const dev=devDefinitions.value.map(d=>({key:`dev-${d.fileId}`,source:'DEVELOPMENT' as const,name:stripExt(d.name),code:d.workflowCode,status:d.lifecycleStatus,version:`V${d.currentVersion}`,
    schedule:scheduleLabel(d),upstreamCount:d.upstreamCount,downstreamCount:d.downstreamCount,runtimeStatus:d.runtimeStatus,nextPlannedAt:d.nextPlannedAt,updatedAt:d.updatedAt,dev:d}))
  const custom=rows.value.map(w=>({key:`wf-${w.id}`,source:'CUSTOM' as const,name:w.name,code:w.workflowCode,status:w.status,version:w.publishedVersion?`V${w.publishedVersion}`:'草稿',
    schedule:'工作流调度',upstreamCount:w.edges.length,downstreamCount:w.nodes.length,runtimeStatus:w.status,updatedAt:w.updatedAt,workflow:w}))
  const q=listSearch.value.trim().toLowerCase()
  return [...projects,...dev,...custom].filter(r=>(sourceFilter.value==='ALL'||r.source===sourceFilter.value)&&(!q||r.name.toLowerCase().includes(q)||r.code.toLowerCase().includes(q))&&(statusFilter.value==='ALL'||runtimeClass(r.runtimeStatus)===statusFilter.value||r.status===statusFilter.value))
})
const filteredDevTasks=computed(()=>files.value.filter(f=>{if(projectMode.value&&f.projectId!==currentProject.value?.projectId)return false;if((developmentMode.value||projectMode.value)&&f.fileType?.toUpperCase()!=='SQL')return false;if(taskFilter.value!=='ALL'&&f.fileType?.toUpperCase()!==taskFilter.value)return false;const q=taskSearch.value.trim().toLowerCase();return !q||f.name.toLowerCase().includes(q)||(f.ownerName||'').toLowerCase().includes(q)}))
const selectedDevFile=computed(()=>nodeDraft.devFileId?files.value.find(f=>f.id===nodeDraft.devFileId):undefined)
const selectedIntegrationTask=computed(()=>nodeDraft.integrationTaskId?integrationTasks.value.find(t=>t.id===nodeDraft.integrationTaskId):undefined)
const selectedDependencies=computed(()=>{graphRevision.value;if(!graph||!selectedCode.value)return{ups:[],downs:[]};const nameOf=(id:string)=>{const n=graph?.getCellById(id);return n?.isNode()?((n.getData() as NodeData).name||id):id};return{ups:graph.getEdges().filter(e=>String(e.getTargetCellId())===selectedCode.value).map(e=>nameOf(String(e.getSourceCellId()))),downs:graph.getEdges().filter(e=>String(e.getSourceCellId())===selectedCode.value).map(e=>nameOf(String(e.getTargetCellId())))}})
const selectedEdgeInfo=computed(()=>{graphRevision.value;if(!graph||!selectedEdgeId.value)return undefined;const e=graph.getCellById(selectedEdgeId.value);if(!e?.isEdge())return undefined;const nameOf=(id:string)=>{const n=graph?.getCellById(id);return n?.isNode()?((n.getData() as NodeData).name||id):id};return{source:nameOf(String(e.getSourceCellId())),target:nameOf(String(e.getTargetCellId()))}})

async function loadBase(){
  loading.value=true
  try{
    const [custom,defs,projectDefs,projects,offline,sources]=await Promise.all([workflowApi.list(),workflowApi.developmentDefinitions(),workflowApi.projectDefinitions(),developmentApi.projects(),integrationApi.list(),dataSourceApi.list()])
    rows.value=custom;devDefinitions.value=defs;projectDefinitions.value=projectDefs;integrationTasks.value=offline;scheduleSources.value=sources.filter(x=>x.type==='STARROCKS')
    files.value=(await Promise.all(projects.map(p=>developmentApi.files(p.id)))).flat()
  }catch(e){ElMessage.error(msg(e))}finally{loading.value=false}
}
async function boot(){await loadBase();const fileId=Number(route.query.fileId||0);if(fileId)await openDevelopmentWorkflow(fileId)}
function newWorkflow(){developmentMode.value=false;projectMode.value=false;focusFileId.value=undefined;currentDev.value=undefined;currentProject.value=undefined;current.value=null;workflowSchedule.value=undefined;form.name='';form.description='';editorOpen.value=true;dirty.value=false;void nextTick(()=>{initGraph();startRuntimePolling()})}
async function openRow(row:ListRow){if(row.source==='PROJECT'&&row.project)return openProjectWorkflow(row.project.projectId);if(row.source==='DEVELOPMENT'&&row.dev)return openDevelopmentWorkflow(row.dev.fileId);if(row.workflow)return openCustomWorkflow(row.workflow)}
async function openProjectWorkflow(projectId:number){try{const def=projectDefinitions.value.find(x=>x.projectId===projectId);const view=await workflowApi.projectGraph(projectId);projectMode.value=true;developmentMode.value=false;currentProject.value=def;currentDev.value=undefined;focusFileId.value=undefined;focusSchedule.value=undefined;current.value=view;form.name=view.name;form.description=view.description||'';await openEditor(view)}catch(e){ElMessage.error(msg(e))}}
async function openDevelopmentWorkflow(fileId:number){
  try{
    const def=devDefinitions.value.find(x=>x.fileId===fileId)
    const [view,schedule]=await Promise.all([workflowApi.developmentGraph(fileId),developmentApi.schedule(fileId)])
    projectMode.value=false;developmentMode.value=true;focusFileId.value=fileId;currentDev.value=def;focusSchedule.value=schedule;fillScheduleDraft(schedule);current.value=view;form.name=view.name;form.description=view.description||''
    await openEditor(view,fileId)
  }catch(e){ElMessage.error(msg(e))}
}
async function openCustomWorkflow(row:WorkflowView){
  try{
    projectMode.value=false;developmentMode.value=false;currentProject.value=undefined;focusFileId.value=undefined;currentDev.value=undefined;focusSchedule.value=undefined
    current.value=await workflowApi.get(row.id);form.name=current.value.name;form.description=current.value.description||''
    try{workflowSchedule.value=await workflowApi.schedule(row.id)}catch{workflowSchedule.value=undefined}
    await openEditor(current.value)
  }catch(e){ElMessage.error(msg(e))}
}

function fillScheduleDraft(s?:DevelopmentSchedule){
  Object.assign(scheduleDraft,{enabled:s?.enabled||false,cycleType:s?.cycleType||'DAILY',executionTime:s?.executionTime||'02:00',cronExpression:s?.cronExpression||'0 0 2 * * ?',timezone:s?.timezone||'Asia/Shanghai',dataSourceId:s?.dataSourceId,databaseName:s?.databaseName||'',bizDateParam:s?.bizDateParam||'${system.biz.date-1}',retryTimes:s?.retryTimes??3,retryIntervalMinutes:s?.retryIntervalMinutes??5,timeoutMinutes:s?.timeoutMinutes??120})
}
function syncScheduleCron(){const [h,m]=(scheduleDraft.executionTime||'02:00').split(':').map(Number);if(scheduleDraft.cycleType==='DAILY')scheduleDraft.cronExpression=`0 ${m||0} ${h||0} * * ?`;else if(scheduleDraft.cycleType==='HOURLY')scheduleDraft.cronExpression=`0 ${m||0} * * * ?`;else if(scheduleDraft.cycleType==='WEEKLY')scheduleDraft.cronExpression=`0 ${m||0} ${h||0} ? * MON`;else if(scheduleDraft.cycleType==='MONTHLY')scheduleDraft.cronExpression=`0 ${m||0} ${h||0} 1 * ?`}
function currentUpstreamIds(){if(!graph||!focusFileId.value)return[] as number[];const target=`task_${focusFileId.value}`;return graph.getEdges().filter(e=>String(e.getTargetCellId())===target).map(e=>{const source=graph?.getCellById(String(e.getSourceCellId()));return source?.isNode()?Number((source.getData() as NodeData).devFileId||0):0}).filter(x=>x>0)}
async function saveDevelopmentSchedule(){
  if(!focusFileId.value||!currentDev.value)return
  if(currentDev.value.lifecycleStatus==='ONLINE')return ElMessage.warning('任务已上线，请先下线后再修改调度')
  if(scheduleDraft.enabled&&!scheduleDraft.dataSourceId)return ElMessage.warning('启用调度前请选择 StarRocks 数据源')
  saving.value=true
  try{
    const saved=await developmentApi.saveSchedule(focusFileId.value,{...scheduleDraft,upstreamFileIds:currentUpstreamIds()})
    focusSchedule.value=saved;fillScheduleDraft(saved);await loadBase();currentDev.value=devDefinitions.value.find(x=>x.fileId===focusFileId.value)
    const view=await workflowApi.developmentGraph(focusFileId.value);current.value=view;initGraph(view);ElMessage.success('调度已同步到数据开发')
  }catch(e){ElMessage.error(msg(e))}finally{saving.value=false}
}
async function deleteDevelopmentSchedule(){
  if(!focusFileId.value||!currentDev.value)return
  if(currentDev.value.lifecycleStatus==='ONLINE')return ElMessage.warning('任务已上线，请先下线后再删除调度')
  try{await ElMessageBox.confirm('删除当前调度配置？任务依赖关系会保留。','删除调度',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});const saved=await developmentApi.deleteSchedule(focusFileId.value);focusSchedule.value=saved;fillScheduleDraft(saved);await loadBase();currentDev.value=devDefinitions.value.find(x=>x.fileId===focusFileId.value);ElMessage.success('调度配置已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}
}
async function toggleLifecycle(row:ListRow){
  if(row.source!=='DEVELOPMENT'||!row.dev)return
  try{if(row.dev.lifecycleStatus==='ONLINE')await developmentApi.offlineFile(row.dev.fileId);else await developmentApi.onlineFile(row.dev.fileId);await loadBase();ElMessage.success(row.dev.lifecycleStatus==='ONLINE'?'已下线':'已上线，等待发布')}catch(e){ElMessage.error(msg(e))}
}
async function deleteDefinition(row:ListRow){
  try{
    await ElMessageBox.confirm(`确认删除工作流“${row.name}”？${row.source==='DEVELOPMENT'?'对应的数据开发脚本也会进入回收站。':''}`,'删除确认',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'})
    if(row.source==='DEVELOPMENT'&&row.dev){if(row.dev.lifecycleStatus==='ONLINE')return ElMessage.warning('任务已上线，请先下线后再删除');await developmentApi.deleteFile(row.dev.fileId)}else if(row.workflow)await workflowApi.remove(row.workflow.id)
    await loadBase();ElMessage.success('已删除')
  }catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}
}
function handleMore(command:unknown,row:ListRow){const action=String(command);if(action==='edit')return void openRow(row);if(action==='lifecycle')return void toggleLifecycle(row);if(action==='delete')return void deleteDefinition(row)}
function focusProjectTask(file:DevFile){const n=graph?.getNodes().find(x=>(x.getData() as NodeData).devFileId===file.id);if(n){graph?.centerCell(n);void selectNode(String(n.id))}}
async function previewImpact(){if(!projectMode.value||!currentProject.value||!selectedDevFile.value)return;impactLoading.value=true;impactOpen.value=true;try{impactView.value=await workflowApi.projectImpact(currentProject.value.projectId,selectedDevFile.value.id,impactIncludeSource.value)}catch(e){ElMessage.error(msg(e))}finally{impactLoading.value=false}}
function stopRerunPolling(){if(rerunTimer!==undefined){window.clearInterval(rerunTimer);rerunTimer=undefined}}
function pollRerun(batchId:number){stopRerunPolling();rerunTimer=window.setInterval(async()=>{try{const b=await workflowApi.projectRerun(batchId);rerunBatch.value=b;if(['SUCCESS','FAILED'].includes(b.status)){stopRerunPolling();void refreshNodeRuntimes();void loadBase()}}catch{}},2000)}
async function startImpactRerun(){if(!currentProject.value||!selectedDevFile.value)return;impactLoading.value=true;try{const b=await workflowApi.startProjectRerun({projectId:currentProject.value.projectId,sourceFileId:selectedDevFile.value.id,includeSource:impactIncludeSource.value,businessDate:impactBusinessDate.value});rerunBatch.value=b;impactOpen.value=true;pollRerun(b.id);ElMessage.success('下游重跑批次已创建')}catch(e){ElMessage.error(msg(e))}finally{impactLoading.value=false}}
async function openEditor(view?:WorkflowView|null,focusId?:number){selectedCode.value='';selectedEdgeId.value='';selectedSchedule.value=undefined;selectedIntegrationSchedule.value=undefined;inspectorTab.value='prop';editorOpen.value=true;dirty.value=false;await nextTick();initGraph(view);startRuntimePolling();void refreshNodeRuntimes();if(focusId){const n=graph?.getNodes().find(x=>(x.getData() as NodeData).devFileId===focusId);if(n){graph?.centerCell(n);await selectNode(String(n.id))}}}
function closeEditor(){stopRuntimePolling();stopRerunPolling();editorNavOpen.value=false;graph?.dispose();graph=undefined;editorOpen.value=false;projectMode.value=false;developmentMode.value=false;currentProject.value=undefined;focusFileId.value=undefined;selectedCode.value='';selectedEdgeId.value='';if(route.query.fileId)void router.replace({path:'/workflow/definitions'})}
function goPlatform(path:string){closeEditor();void router.push(path)}

function shortTime(v?:string){if(!v)return'—';const d=new Date(v);if(Number.isNaN(d.getTime()))return v;const p=(n:number)=>String(n).padStart(2,'0');return `${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`}
function nodeVisual(data:NodeData){
  const dev=data.devFileId?files.value.find(f=>f.id===data.devFileId):undefined,off=data.integrationTaskId?integrationTasks.value.find(t=>t.id===data.integrationTaskId):undefined
  const type=(dev?.fileType||data.nodeType||'SQL').toUpperCase(),icon=type==='PYTHON'?'PY':type==='SHELL'?'SH':type==='SEATUNNEL'?'ST':type==='CONDITION'?'◇':'SQL'
  const meta=dev?`V${dev.currentVersion} · ${lifecycleLabel(dev.lifecycleStatus)}`:off?'已绑定离线任务':type==='CONDITION'?'条件节点':'未绑定离线任务'
  return{icon,type,meta,runClass:runtimeClass(data.runtimeStatus),runLabel:type==='CONDITION'?'条件':runtimeLabel(data.runtimeStatus),schedule:shortTime(data.plannedAt||data.nextPlannedAt),finished:shortTime(data.finishedAt)}
}
function createWorkflowNode(cell:any){
  const data=cell.getData() as NodeData,v=nodeVisual(data),root=document.createElement('div')
  root.className=`wf-task-card type-${v.type.toLowerCase()} runtime-${v.runClass}${data.selected?' is-selected':''}${data.focus?' is-focus':''}`;root.style.width='184px';root.style.height='78px'
  const top=document.createElement('div');top.className='wf-task-top';root.appendChild(top)
  const ico=document.createElement('span');ico.className='wf-task-icon';ico.textContent=v.icon;top.appendChild(ico)
  const main=document.createElement('div');main.className='wf-task-main';main.innerHTML=`<b>${data.name}</b><small>${v.meta}</small>`;top.appendChild(main)
  const state=document.createElement('span');state.className=`wf-task-state ${v.runClass}`;state.innerHTML=`<i></i>${v.runLabel}`;top.appendChild(state)
  const bottom=document.createElement('div');bottom.className='wf-task-bottom';bottom.innerHTML=`<span><em>调度</em><b>${v.schedule}</b></span><span><em>完成</em><b>${v.finished}</b></span>`;root.appendChild(bottom)
  return root
}
Shape.HTML.register({shape:'datasphere-workflow-task',width:184,height:78,effect:['data'],html:createWorkflowNode})

function initGraph(view?:WorkflowView|null){
  graph?.dispose();if(!canvasRef.value)return
  graph=new Graph({container:canvasRef.value,autoResize:true,background:{color:'#f8fafc'},grid:{visible:true,size:18,type:'dot',args:{color:'#dfe6ef'}},panning:true,mousewheel:{enabled:true,modifiers:['ctrl','meta'],minScale:.65,maxScale:1.5},connecting:{connector:'smooth',anchor:'center',connectionPoint:'boundary',allowBlank:false,allowLoop:false,allowMulti:false,snap:true,createEdge(){return graph!.createEdge({zIndex:0,attrs:{line:{stroke:'#aeb8c6',strokeWidth:1.4,targetMarker:{name:'block',width:7,height:7}}}})}}})
  if(view){const map=new Map(view.nodes.map(n=>[n.id,n.nodeCode]));view.nodes.forEach(n=>addGraphNode(n,false));view.edges.forEach(e=>{const s=map.get(e.sourceNodeId),t=map.get(e.targetNodeId);if(s&&t)graph?.addEdge({source:{cell:s,port:'out'},target:{cell:t,port:'in'},attrs:{line:{stroke:'#aeb8c6',strokeWidth:1.4,targetMarker:{name:'block',width:7,height:7}}}})})}
  graph.on('node:click',({node})=>void selectNode(String(node.id)))
  graph.on('blank:click',clearSelection)
  graph.on('node:moved',()=>{if(!developmentMode.value&&!projectMode.value)dirty.value=true;updateStats()})
  graph.on('edge:connected',({edge})=>{if(!validateNewEdge(edge)){graph?.removeCell(edge);return}dirty.value=true;updateStats()})
  graph.on('edge:click',({edge})=>selectEdge(String(edge.id)))
  graph.on('edge:dblclick',({edge})=>{if(canChangeEdge(edge)){graph?.removeCell(edge);clearSelection();dirty.value=true;updateStats()}})
  dirty.value=false;updateStats();setTimeout(()=>{graph?.zoomTo(1);graphScale.value=1},0)
}
function addGraphNode(n?:Partial<WorkflowNode>,select=true){
  if(!graph)return
  const cfg=parseConfig(n?.configJson),integrationTaskId=Number(cfg.integrationTaskId||0)||undefined,dev=n?.devFileId?files.value.find(f=>f.id===n.devFileId):undefined,off=integrationTaskId?integrationTasks.value.find(t=>t.id===integrationTaskId):undefined
  const code=n?.nodeCode||`node_${Date.now()}_${Math.random().toString(16).slice(2,7)}`,nodeType=(n?.nodeType||dev?.fileType||(off?'SEATUNNEL':'CONDITION')) as NodeKind
  const data:NodeData={name:n?.name||stripExt(dev?.name||off?.name||(nodeType==='CONDITION'?'条件分支':'SeaTunnel 节点')),nodeType,devFileId:n?.devFileId,integrationTaskId,configJson:n?.configJson||'{}',taskVersion:dev?.currentVersion,lifecycleStatus:dev?.lifecycleStatus,ownerName:dev?.ownerName,focus:Boolean(n?.devFileId&&n.devFileId===focusFileId.value)}
  graph.addNode({id:code,shape:'datasphere-workflow-task',x:n?.x??70+(graph.getNodes().length%3)*252,y:n?.y??88+Math.floor(graph.getNodes().length/3)*112,width:184,height:78,data,ports:{groups:{in:{position:'left',attrs:{circle:{r:4.5,magnet:true,stroke:'#97a7ba',strokeWidth:1.4,fill:'#fff'}}},out:{position:'right',attrs:{circle:{r:4.5,magnet:true,stroke:'#97a7ba',strokeWidth:1.4,fill:'#fff'}}}},items:[{id:'in',group:'in'},{id:'out',group:'out'}]}})
  if(select)void selectNode(code);updateStats();void refreshNodeRuntimes()
}
function addDevTask(file:DevFile){if(projectMode.value){focusProjectTask(file);return}if(developmentMode.value&&file.fileType?.toUpperCase()!=='SQL')return;const existing=graph?.getNodes().find(n=>(n.getData() as NodeData).devFileId===file.id);if(existing){graph?.centerCell(existing);void selectNode(String(existing.id));return}addGraphNode({name:stripExt(file.name),nodeType:file.fileType.toUpperCase() as NodeKind,devFileId:file.id,nodeCode:`task_${file.id}`});dirty.value=true}
function addSpecial(type:'SEATUNNEL'|'CONDITION'){if(developmentMode.value)return;addGraphNode({name:type==='CONDITION'?'条件分支':'SeaTunnel 节点',nodeType:type,configJson:type==='CONDITION'?JSON.stringify({expression:"status == 'SUCCESS'"}):'{}'});dirty.value=true}
function clearSelection(){selectedCode.value='';selectedEdgeId.value='';selectedSchedule.value=undefined;selectedIntegrationSchedule.value=undefined;refreshSelection();graphRevision.value++}
function selectEdge(id:string){selectedEdgeId.value=id;selectedCode.value='';selectedSchedule.value=undefined;selectedIntegrationSchedule.value=undefined;refreshSelection();graphRevision.value++}
async function selectNode(code:string){selectedCode.value=code;selectedEdgeId.value='';inspectorTab.value='prop';const n=graph?.getCellById(code);if(!n?.isNode())return;const d=n.getData() as NodeData;Object.assign(nodeDraft,d);conditionExpression.value=String(parseConfig(d.configJson).expression||"status == 'SUCCESS'");selectedSchedule.value=undefined;selectedIntegrationSchedule.value=undefined;refreshSelection();if(d.devFileId){try{selectedSchedule.value=await developmentApi.schedule(d.devFileId)}catch{}}if(d.integrationTaskId){try{selectedIntegrationSchedule.value=await integrationApi.schedule(d.integrationTaskId)}catch{}}graphRevision.value++}
function refreshSelection(){graph?.getNodes().forEach(n=>{const d=n.getData() as NodeData,on=String(n.id)===selectedCode.value;if(Boolean(d.selected)!==on)n.setData({...d,selected:on})});graph?.getEdges().forEach(e=>{const on=String(e.id)===selectedEdgeId.value;e.attr('line/stroke',on?'#4f7fe8':'#aeb8c6');e.attr('line/strokeWidth',on?2:1.4)})}
function canChangeEdge(edge:any){
  if(projectMode.value){ElMessage.info('项目工作流自动读取数据开发依赖，请在单任务工作流中修改依赖');return false}
  const target=graph?.getCellById(String(edge.getTargetCellId())),d=target?.isNode()?(target.getData() as NodeData):undefined
  if(developmentMode.value&&d?.devFileId!==focusFileId.value){ElMessage.warning('当前只允许修改本工作流脚本的上游依赖');return false}
  const f=d?.devFileId?files.value.find(x=>x.id===d.devFileId):undefined
  if(f?.fileType?.toUpperCase()==='SQL'&&f.lifecycleStatus==='ONLINE'){ElMessage.warning(`任务“${stripExt(f.name)}”已上线，请先下线后再修改依赖`);return false}
  return true
}
function createsCycle(source:string,target:string){if(!graph)return false;const out=new Map<string,string[]>();graph.getNodes().forEach(n=>out.set(String(n.id),[]));graph.getEdges().forEach(e=>{const s=String(e.getSourceCellId()),t=String(e.getTargetCellId());if(s!==source||t!==target)out.get(s)?.push(t)});const stack=[target],seen=new Set<string>();while(stack.length){const x=stack.pop()!;if(x===source)return true;if(seen.has(x))continue;seen.add(x);stack.push(...(out.get(x)||[]))}return false}
function validateNewEdge(edge:any){const s=String(edge.getSourceCellId()),t=String(edge.getTargetCellId());if(!s||!t||s===t)return false;if(!canChangeEdge(edge))return false;if(createsCycle(s,t)){ElMessage.warning('依赖关系会形成环路');return false}return true}
function applySpecialNode(){const n=graph?.getCellById(selectedCode.value);if(!n?.isNode()||selectedDevFile.value)return;const d=n.getData() as NodeData;if(d.nodeType==='SEATUNNEL'){const task=selectedIntegrationTask.value;n.setData({...d,name:task?.name||'SeaTunnel 节点',integrationTaskId:nodeDraft.integrationTaskId,configJson:JSON.stringify(nodeDraft.integrationTaskId?{integrationTaskId:nodeDraft.integrationTaskId}:{})})}else n.setData({...d,name:nodeDraft.name||'条件分支',configJson:JSON.stringify({expression:conditionExpression.value})});dirty.value=true;void selectNode(String(n.id));void refreshNodeRuntimes()}
function removeNode(){if(projectMode.value)return ElMessage.info('项目工作流节点来自数据开发，不能直接删除');if(developmentMode.value)return ElMessage.info('数据开发工作流中的任务节点来自真实脚本，不能删除；请删除依赖连线');const n=graph?.getCellById(selectedCode.value);if(!n)return;graph?.removeCell(n);clearSelection();dirty.value=true;updateStats()}
function removeSelectedEdge(){if(!selectedEdgeId.value)return;const e=graph?.getCellById(selectedEdgeId.value);if(e?.isEdge()&&canChangeEdge(e)){graph?.removeCell(e);clearSelection();dirty.value=true;updateStats()}}
function payload(){const nodes=(graph?.getNodes()||[]).map(n=>{const p=n.getPosition(),d=n.getData() as NodeData;return{name:d.name,nodeType:d.nodeType,devFileId:d.devFileId,configJson:d.configJson||'{}',x:Math.round(p.x),y:Math.round(p.y),nodeCode:String(n.id)}});const edges=(graph?.getEdges()||[]).map(e=>({sourceNodeCode:String(e.getSourceCellId()),targetNodeCode:String(e.getTargetCellId())}));return{name:form.name.trim()||current?.value?.name||'工作流',description:form.description.trim(),nodes,edges}}

async function save(){
  saving.value=true
  try{
    if(developmentMode.value&&focusFileId.value){const saved=await workflowApi.saveDevelopmentGraph(focusFileId.value,payload());current.value=saved;await loadBase();currentDev.value=devDefinitions.value.find(x=>x.fileId===focusFileId.value);focusSchedule.value=await developmentApi.schedule(focusFileId.value);initGraph(saved);dirty.value=false;ElMessage.success('上游依赖已同步回数据开发');return}
    if(!form.name.trim())return ElMessage.warning('请输入工作流名称')
    if(!graph?.getNodes().length)return ElMessage.warning('请至少添加一个任务节点')
    const saved=current.value?await workflowApi.update(current.value.id,payload()):await workflowApi.create(payload());current.value=await workflowApi.get(saved.id);form.name=current.value.name;form.description=current.value.description||'';await loadBase();initGraph(current.value);dirty.value=false;ElMessage.success('工作流已保存')
  }catch(e){ElMessage.error(msg(e))}finally{saving.value=false}
}
async function publish(){if(developmentMode.value)return;await save();if(!current.value)return;try{const req=await releaseApi.request({resourceType:'WORKFLOW',resourceId:current.value.id,resourceName:form.name,requestedVersion:current.value.publishedVersion+1});ElMessage.success(req.status==='PENDING_APPROVAL'?'发布申请已提交':'工作流已发布');await loadBase()}catch(e){ElMessage.error(msg(e))}}
async function runCurrent(){try{if(developmentMode.value&&focusFileId.value){await operationsApi.startTask('DEVELOPMENT',focusFileId.value);ElMessage.success('开发任务已提交运行');void refreshNodeRuntimes();return}if(!current.value)return ElMessage.warning('请先保存工作流');await workflowApi.run(current.value.id);ElMessage.success('工作流实例已提交')}catch(e){ElMessage.error(msg(e))}}
async function runRow(row:ListRow){try{if(row.source==='DEVELOPMENT'&&row.dev)await operationsApi.startTask('DEVELOPMENT',row.dev.fileId);else if(row.workflow)await workflowApi.run(row.workflow.id);ElMessage.success('运行已提交');await loadBase()}catch(e){ElMessage.error(msg(e))}}
function openDevelopment(){const id=nodeDraft.devFileId||focusFileId.value;if(id)void router.push({path:'/development/workspace',query:{fileId:String(id)}})}
async function onIntegrationTaskChange(id?:number){selectedIntegrationSchedule.value=undefined;if(id){try{selectedIntegrationSchedule.value=await integrationApi.schedule(id)}catch{}}}

function autoLayout(){if(!graph)return;const nodes=graph.getNodes(),edges=graph.getEdges(),indegree=new Map<string,number>(),out=new Map<string,string[]>();nodes.forEach(n=>{indegree.set(String(n.id),0);out.set(String(n.id),[])});edges.forEach(e=>{const s=String(e.getSourceCellId()),t=String(e.getTargetCellId());if(indegree.has(t)&&out.has(s)){indegree.set(t,(indegree.get(t)||0)+1);out.get(s)!.push(t)}});const queue=[...indegree.entries()].filter(([,v])=>v===0).map(([k])=>k),level=new Map<string,number>();queue.forEach(k=>level.set(k,0));while(queue.length){const id=queue.shift()!,l=level.get(id)||0;for(const n of out.get(id)||[]){level.set(n,Math.max(level.get(n)||0,l+1));indegree.set(n,(indegree.get(n)||1)-1);if(indegree.get(n)===0)queue.push(n)}}const layers=new Map<number,string[]>();nodes.forEach(n=>{const l=level.get(String(n.id))||0;layers.set(l,[...(layers.get(l)||[]),String(n.id)])});for(const [l,ids] of layers)ids.forEach((id,i)=>{const n=graph?.getCellById(id);if(n?.isNode())n.setPosition(70+l*252,88+i*112)});if(!developmentMode.value&&!projectMode.value)dirty.value=true;updateStats();graph.zoomTo(1);graphScale.value=1}
function updateStats(){if(!graph){Object.assign(stats,{nodes:0,edges:0,roots:0,leaves:0});return}const nodes=graph.getNodes(),edges=graph.getEdges(),ins=new Set(edges.map(e=>String(e.getTargetCellId()))),outs=new Set(edges.map(e=>String(e.getSourceCellId())));Object.assign(stats,{nodes:nodes.length,edges:edges.length,roots:nodes.filter(n=>!ins.has(String(n.id))).length,leaves:nodes.filter(n=>!outs.has(String(n.id))).length});graphRevision.value++}
function zoom(delta:number){if(!graph)return;graphScale.value=Math.max(.65,Math.min(1.5,Math.round((graphScale.value+delta)*10)/10));graph.zoomTo(graphScale.value)}
function fit(){if(!graph)return;graph.zoomToFit({padding:60,maxScale:1});graphScale.value=Math.round(graph.zoom()*100)/100}
function stopRuntimePolling(){if(runtimeTimer!==undefined){window.clearInterval(runtimeTimer);runtimeTimer=undefined}}
function startRuntimePolling(){stopRuntimePolling();runtimeTimer=window.setInterval(()=>void refreshNodeRuntimes(),5000)}
async function refreshNodeRuntimes(){if(!graph||!editorOpen.value)return;await Promise.all(graph.getNodes().map(async n=>{const d=n.getData() as NodeData;try{if(d.devFileId){const r=await developmentApi.scheduleRuntime(d.devFileId);n.setData({...d,runtimeStatus:r.status,plannedAt:r.plannedAt,finishedAt:r.finishedAt,nextPlannedAt:r.nextPlannedAt,errorMessage:r.errorMessage})}else if(d.integrationTaskId){const [summary,instances]=await Promise.all([integrationApi.summary(d.integrationTaskId),integrationApi.instances(d.integrationTaskId)]);const latest=[...instances].sort((a,b)=>String(b.startedAt||b.finishedAt||'').localeCompare(String(a.startedAt||a.finishedAt||'')))[0];n.setData({...d,runtimeStatus:latest?.status,plannedAt:summary.nextRunAt,finishedAt:latest?.finishedAt,errorMessage:latest?.message})}}catch{}}));graphRevision.value++}
function onKeydown(e:KeyboardEvent){if(!['Delete','Backspace'].includes(e.key)||['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement)?.tagName))return;if(selectedEdgeId.value){e.preventDefault();removeSelectedEdge()}else if(selectedCode.value&&!developmentMode.value){e.preventDefault();removeNode()}}

onMounted(()=>{void boot();window.addEventListener('keydown',onKeydown)})
onBeforeUnmount(()=>{stopRuntimePolling();stopRerunPolling();graph?.dispose();window.removeEventListener('keydown',onKeydown)})
</script>

<template>
<div class="workflow-page">
  <section v-if="!editorOpen" class="workflow-list-page">
    <div class="page-head"><div><h1>工作流</h1><p>数据开发脚本自动成为工作流；调度、依赖和运行状态与数据开发保持同一份配置。</p></div><div class="page-actions"><button class="btn" @click="loadBase">刷新</button><button class="btn primary" @click="newWorkflow">+ 新建</button></div></div>
    <div class="summary-strip">
      <div><b>{{projectDefinitions.length}}</b><span>项目工作流</span></div><div><b>{{devDefinitions.length}}</b><span>数据开发工作流</span></div><div><b>{{devDefinitions.filter(x=>x.scheduleEnabled).length}}</b><span>已启用调度</span></div><div><b>{{devDefinitions.filter(x=>runtimeClass(x.runtimeStatus)==='failed').length}}</b><span>异常</span></div>
    </div>
    <div class="list-card">
      <div class="list-toolbar"><el-input v-model="listSearch" :prefix-icon="Search" clearable placeholder="搜索工作流名称 / 编码"/><div class="source-tabs"><button v-for="x in [{k:'ALL',n:'全部'},{k:'PROJECT',n:'项目工作流'},{k:'DEVELOPMENT',n:'数据开发'},{k:'CUSTOM',n:'编排工作流'}]" :key="x.k" :class="{on:sourceFilter===x.k}" @click="sourceFilter=x.k as SourceFilter">{{x.n}}</button></div><el-select v-model="statusFilter"><el-option label="全部状态" value="ALL"/><el-option label="运行中" value="running"/><el-option label="等待依赖" value="waiting"/><el-option label="成功" value="success"/><el-option label="失败" value="failed"/><el-option label="已上线" value="ONLINE"/><el-option label="草稿" value="DRAFT"/></el-select><span>{{definitionRows.length}} 个工作流</span></div>
      <div class="table-wrap"><table><thead><tr><th>工作流名称</th><th>来源</th><th>调度</th><th>最近状态</th><th>下次调度</th><th>最近修改</th><th>操作</th></tr></thead><tbody>
        <tr v-for="r in definitionRows" :key="r.key"><td><b class="wf-name" @click="openRow(r)">{{r.name}}</b><small>{{r.code}} · {{r.version}}</small></td><td><span :class="['source-tag',r.source.toLowerCase()]">{{r.source==='PROJECT'?'项目工作流':r.source==='DEVELOPMENT'?'数据开发':'编排工作流'}}</span></td><td><span :class="['schedule-state',{off:r.source==='DEVELOPMENT'&&!r.dev?.scheduleEnabled}]">{{r.schedule}}</span></td><td><span :class="['runtime-pill',runtimeClass(r.runtimeStatus)]"><i></i>{{runtimeLabel(r.runtimeStatus)}}</span></td><td class="nowrap">{{fmt(r.nextPlannedAt)}}</td><td class="nowrap">{{fmt(r.updatedAt)}}</td><td class="op-cell"><span class="link" @click="openRow(r)">详情</span><el-dropdown trigger="click" @command="handleMore($event,r)"><span class="more-link">更多⌄</span><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">{{r.source==='PROJECT'?'查看项目 DAG':'编辑'}}</el-dropdown-item><el-dropdown-item v-if="r.source==='DEVELOPMENT'" command="lifecycle">{{r.dev?.lifecycleStatus==='ONLINE'?'下线':'上线'}}</el-dropdown-item><el-dropdown-item v-if="r.source!=='PROJECT'" divided command="delete">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></td></tr>
        <tr v-if="!definitionRows.length"><td colspan="7"><div class="empty-row">没有匹配的工作流</div></td></tr>
      </tbody></table></div>
    </div>
  </section>

  <section v-else class="editor-shell">
    <header class="editor-head"><button class="icon-btn" @click="closeEditor">‹</button><button class="icon-btn menu" @click="editorNavOpen=true">☰</button><div class="editor-title"><div class="crumb"><span>工作流</span><i>/</i><strong>{{projectMode?`${currentProject?.name||''} · 项目工作流`:developmentMode?currentDev?.name:(current?form.name:'新建编排工作流')}}</strong></div><div class="editor-tags"><span :class="['source-tag',projectMode?'project':developmentMode?'development':'custom']">{{projectMode?'项目工作流':developmentMode?'数据开发':'编排工作流'}}</span><span v-if="developmentMode" class="tag">{{currentDev?.lifecycleStatus==='ONLINE'?'已上线':'未上线'}}</span><span v-if="projectMode" class="tag">{{currentProject?.taskCount||0}} 个任务</span><span v-if="!projectMode" class="tag">{{developmentMode?`V${currentDev?.currentVersion||0}`:(current?.publishedVersion?`V${current.publishedVersion}`:'草稿')}}</span><span v-if="dirty" class="tag warn">未保存</span></div></div><div class="editor-actions"><button class="btn" @click="autoLayout">自动布局</button><button v-if="projectMode" class="btn" @click="currentProject&&openProjectWorkflow(currentProject.projectId)">刷新</button><template v-else><button class="btn" :disabled="saving" @click="save">{{saving?'保存中…':developmentMode?'保存依赖':'保存'}}</button><button class="btn" @click="runCurrent">运行</button><button v-if="developmentMode" class="btn" @click="openDevelopment">数据开发</button><button v-else class="btn primary" @click="publish">发布</button></template></div></header>
    <div class="editor-meta" v-if="projectMode"><div><span>项目</span><b>{{currentProject?.name||'—'}}</b></div><div><span>任务</span><b>{{currentProject?.taskCount||0}}</b></div><div><span>已启用调度</span><b>{{currentProject?.enabledSchedules||0}}</b></div><div><span>运行中</span><b>{{currentProject?.runningTasks||0}}</b></div><div><span>异常</span><b>{{currentProject?.failedTasks||0}}</b></div><div><span>依赖来源</span><b>数据开发</b></div></div>
    <div class="editor-meta" v-else-if="developmentMode"><div><span>调度</span><b>{{focusSchedule?.enabled?`${cycleLabel(focusSchedule.cycleType)} ${focusSchedule.executionTime||''}`:'未启用'}}</b></div><div><span>Cron</span><b>{{focusSchedule?.cronExpression||'—'}}</b></div><div><span>时区</span><b>{{focusSchedule?.timezone||'—'}}</b></div><div><span>上游</span><b>{{currentDev?.upstreamCount||0}}</b></div><div><span>下游</span><b>{{currentDev?.downstreamCount||0}}</b></div><div><span>下次调度</span><b>{{fmt(currentDev?.nextPlannedAt)}}</b></div></div>
    <div class="editor-meta custom-meta" v-else><input v-model="form.name" placeholder="工作流名称"><input v-model="form.description" placeholder="工作流描述（可选）"><span>调度：{{workflowSchedule?.enabled?'已启用':'未启用'}}</span><span>{{workflowSchedule?.cronExpression||'未配置 Cron'}}</span></div>
    <div class="editor-grid">
      <nav class="editor-rail"><button class="rail active">＋</button><button v-if="!developmentMode" class="rail" @click="addSpecial('CONDITION')">◇</button><button v-if="!developmentMode" class="rail st" @click="addSpecial('SEATUNNEL')">ST</button><button class="rail" @click="autoLayout">⌘</button><button class="rail" @click="fit">⌂</button></nav>
      <aside class="task-panel"><div class="panel-head"><strong>{{projectMode?'项目任务':developmentMode?'可选上游任务':'任务库'}}</strong><span>{{filteredDevTasks.length}}</span></div><div class="task-search"><el-input v-model="taskSearch" :prefix-icon="Search" clearable placeholder="搜索任务 / 负责人"/></div><div class="task-filters"><button v-for="f in ([['ALL','全部'],['SQL','SQL'],['PYTHON','Python'],['SHELL','Shell']] as const)" :key="f[0]" :class="{on:taskFilter===f[0]}" :disabled="(developmentMode||projectMode)&&f[0]!=='ALL'&&f[0]!=='SQL'" @click="taskFilter=f[0]">{{f[1]}}</button></div><div class="task-list"><button v-for="f in filteredDevTasks" :key="f.id" class="task-item" @click="projectMode?focusProjectTask(f):addDevTask(f)"><span class="task-icon">{{f.fileType==='PYTHON'?'PY':f.fileType==='SHELL'?'SH':'SQL'}}</span><span><b>{{f.name}}</b><small>V{{f.currentVersion}} · {{f.ownerName||'—'}} · {{lifecycleLabel(f.lifecycleStatus)}}</small></span><i :class="['life-dot',{online:f.lifecycleStatus==='ONLINE'}]"></i></button><template v-if="!developmentMode&&!projectMode"><div class="divider"></div><div class="group-label">编排节点</div><button class="task-item" @click="addSpecial('CONDITION')"><span class="task-icon condition">◇</span><span><b>条件分支</b><small>根据上游状态控制分支</small></span></button><button class="task-item" @click="addSpecial('SEATUNNEL')"><span class="task-icon seatunnel">ST</span><span><b>SeaTunnel 节点</b><small>在右侧绑定离线同步任务</small></span></button></template></div></aside>
      <main class="canvas-panel"><div class="canvas-tip">{{projectMode?'项目 DAG 自动读取数据开发依赖；选择节点可查看影响范围或重跑全部下游。':developmentMode?'当前脚本的依赖来自数据开发；只允许修改指向当前脚本的上游关系。':'拖动节点右侧端口连接下游；选中连线后 Delete 删除。'}}</div><div class="canvas-tools"><button @click="zoom(-.1)">−</button><span>{{Math.round(graphScale*100)}}%</span><button @click="zoom(.1)">＋</button><button @click="fit">⌂</button></div><div ref="canvasRef" class="canvas-host"></div><div class="canvas-status"><span>{{stats.nodes}} 节点</span><span>{{stats.edges}} 依赖</span><span>{{stats.roots}} 起点</span><span>{{stats.leaves}} 末端</span><span class="push">{{selectedEdgeId?'已选择依赖':selectedCode?'已选择节点':'未选择'}}</span></div></main>
      <aside class="detail-panel"><div class="panel-head"><strong>节点详情</strong><span>{{selectedCode?nodeDraft.name:selectedEdgeId?'依赖连线':'未选择'}}</span></div><div v-if="!selectedCode&&!selectedEdgeId" class="detail-empty"><i>⌁</i><b>选择任务节点</b><span>查看任务属性、调度和上下游依赖。</span></div><div v-else-if="selectedEdgeId" class="edge-detail"><h3>依赖关系</h3><p><b>{{selectedEdgeInfo?.source}}</b> → <b>{{selectedEdgeInfo?.target}}</b></p><button class="btn danger full" @click="removeSelectedEdge">删除依赖</button></div><template v-else><div class="detail-tabs"><button :class="{on:inspectorTab==='prop'}" @click="inspectorTab='prop'">属性</button><button :class="{on:inspectorTab==='schedule'}" @click="inspectorTab='schedule'">调度</button><button :class="{on:inspectorTab==='dep'}" @click="inspectorTab='dep'">依赖</button></div><div class="detail-scroll">
        <template v-if="inspectorTab==='prop'"><div v-if="selectedDevFile" class="hero"><span class="task-icon">{{selectedDevFile.fileType==='PYTHON'?'PY':selectedDevFile.fileType==='SHELL'?'SH':'SQL'}}</span><div><b>{{selectedDevFile.name}}</b><small>{{selectedDevFile.description||'数据开发任务'}}</small></div></div><div v-if="selectedDevFile" class="kv"><span>版本</span><b>V{{selectedDevFile.currentVersion}}</b><span>生命周期</span><b>{{lifecycleLabel(selectedDevFile.lifecycleStatus)}}</b><span>负责人</span><b>{{selectedDevFile.ownerName||'—'}}</b><span>运行状态</span><b>{{runtimeLabel(nodeDraft.runtimeStatus)}}</b><span>计划调度</span><b>{{fmt(nodeDraft.plannedAt||nodeDraft.nextPlannedAt)}}</b><span>实际完成</span><b>{{fmt(nodeDraft.finishedAt)}}</b></div><template v-else-if="nodeDraft.nodeType==='SEATUNNEL'"><div class="hero"><span class="task-icon seatunnel">ST</span><div><b>{{selectedIntegrationTask?.name||'SeaTunnel 节点'}}</b><small>{{selectedIntegrationTask?'已绑定离线同步任务':'请选择离线同步任务'}}</small></div></div><label>离线同步任务</label><el-select v-model="nodeDraft.integrationTaskId" clearable filterable style="width:100%" @change="onIntegrationTaskChange"><el-option v-for="t in integrationTasks" :key="t.id" :label="t.name" :value="t.id"/></el-select><div v-if="selectedIntegrationTask" class="sync-card"><b>{{selectedIntegrationTask.name}}</b><small>{{integrationRoute(selectedIntegrationTask)}}<br>{{integrationMode(selectedIntegrationTask)}}</small></div><div class="row-actions"><button class="btn primary" @click="applySpecialNode">应用绑定</button><button class="btn danger" @click="removeNode">删除节点</button></div></template><template v-else><label>节点名称</label><el-input v-model="nodeDraft.name"/><label>条件表达式</label><el-input v-model="conditionExpression" type="textarea" :rows="5"/><div class="row-actions"><button class="btn primary" @click="applySpecialNode">应用</button><button class="btn danger" @click="removeNode">删除节点</button></div></template><div v-if="selectedDevFile" class="row-actions"><button class="btn" @click="openDevelopment">在数据开发中打开</button></div><div v-if="projectMode&&selectedDevFile" class="project-actions"><button class="btn" @click="previewImpact">查看影响范围</button><button class="btn primary" @click="previewImpact">重跑下游</button></div></template>
        <template v-else-if="inspectorTab==='schedule'"><div v-if="developmentMode&&nodeDraft.devFileId===focusFileId" class="schedule-editor"><div class="schedule-enable"><span><b>任务调度</b><small>{{currentDev?.lifecycleStatus==='ONLINE'?'已上线，需先下线后修改':'修改后同步到数据开发'}}</small></span><el-switch v-model="scheduleDraft.enabled" :disabled="currentDev?.lifecycleStatus==='ONLINE'"/></div><label>执行周期</label><el-select v-model="scheduleDraft.cycleType" :disabled="currentDev?.lifecycleStatus==='ONLINE'" @change="syncScheduleCron"><el-option label="每日" value="DAILY"/><el-option label="每小时" value="HOURLY"/><el-option label="每周" value="WEEKLY"/><el-option label="每月" value="MONTHLY"/><el-option label="Cron" value="CRON"/></el-select><label>执行时间</label><el-input v-model="scheduleDraft.executionTime" :disabled="currentDev?.lifecycleStatus==='ONLINE'" placeholder="02:00" @change="syncScheduleCron"/><label>Cron</label><el-input v-model="scheduleDraft.cronExpression" :disabled="currentDev?.lifecycleStatus==='ONLINE'"/><label>时区</label><el-input v-model="scheduleDraft.timezone" :disabled="currentDev?.lifecycleStatus==='ONLINE'"/><label>StarRocks 数据源</label><el-select v-model="scheduleDraft.dataSourceId" clearable filterable :disabled="currentDev?.lifecycleStatus==='ONLINE'"><el-option v-for="src in scheduleSources" :key="src.id" :label="src.name" :value="src.id"/></el-select><label>Database</label><el-input v-model="scheduleDraft.databaseName" :disabled="currentDev?.lifecycleStatus==='ONLINE'" placeholder="例如 ods"/><div class="schedule-advanced"><div><span>失败重试</span><el-input-number v-model="scheduleDraft.retryTimes" :min="0" :max="20" :disabled="currentDev?.lifecycleStatus==='ONLINE'"/></div><div><span>超时分钟</span><el-input-number v-model="scheduleDraft.timeoutMinutes" :min="1" :max="1440" :disabled="currentDev?.lifecycleStatus==='ONLINE'"/></div></div><div class="row-actions"><button class="btn primary" :disabled="currentDev?.lifecycleStatus==='ONLINE'||saving" @click="saveDevelopmentSchedule">保存调度</button><button class="btn danger" :disabled="currentDev?.lifecycleStatus==='ONLINE'||!focusSchedule?.currentVersion" @click="deleteDevelopmentSchedule">删除调度</button></div></div><div v-else-if="selectedSchedule" class="kv block"><span>状态</span><b>{{selectedSchedule.enabled?'已启用':'未启用'}}</b><span>周期</span><b>{{cycleLabel(selectedSchedule.cycleType)}} {{selectedSchedule.executionTime}}</b><span>Cron</span><b class="mono">{{selectedSchedule.cronExpression}}</b><span>时区</span><b>{{selectedSchedule.timezone}}</b><span>Database</span><b>{{selectedSchedule.databaseName||'—'}}</b></div><div v-else-if="selectedIntegrationTask" class="kv block"><span>状态</span><b>{{selectedIntegrationSchedule?.enabled?'已启用':'未启用'}}</b><span>Cron</span><b class="mono">{{selectedIntegrationSchedule?.cronExpression||'—'}}</b><span>时区</span><b>{{selectedIntegrationSchedule?.timezone||'—'}}</b></div><div v-else class="muted-block">当前节点没有独立调度配置。</div></template>
        <template v-else><div class="dep-block"><h3>上游依赖 <span>{{selectedDependencies.ups.length}}</span></h3><div><span v-for="x in selectedDependencies.ups" :key="x" class="dep-pill">{{x}}</span><em v-if="!selectedDependencies.ups.length">暂无上游</em></div></div><div class="dep-block"><h3>下游任务 <span>{{selectedDependencies.downs.length}}</span></h3><div><span v-for="x in selectedDependencies.downs" :key="x" class="dep-pill">{{x}}</span><em v-if="!selectedDependencies.downs.length">暂无下游</em></div></div></template>
      </div></template></aside>
    </div>
    <div v-if="editorNavOpen" class="nav-mask" @click="editorNavOpen=false"></div><aside :class="['platform-drawer',{open:editorNavOpen}]"><div class="drawer-brand"><span>DS</span><b>DataSphere</b></div><small>平台导航</small><button v-for="item in productNavigation" :key="item.key" :class="{active:item.key==='workflow'}" @click="item.key==='workflow'?editorNavOpen=false:goPlatform(item.path)">{{item.label}}</button></aside>
  </section>
  <el-dialog v-model="impactOpen" title="影响范围与下游重跑" width="620px" @closed="impactView=undefined">
    <div class="impact-head" v-if="selectedDevFile"><div><span>起点任务</span><b>{{stripExt(selectedDevFile.name)}}</b></div><label>业务日期 <el-date-picker v-model="impactBusinessDate" type="date" value-format="YYYY-MM-DD"/></label></div>
    <div class="impact-options"><el-switch v-model="impactIncludeSource" @change="previewImpact"/><span>包含当前任务一起重跑</span><button class="btn" :disabled="impactLoading" @click="previewImpact">刷新范围</button></div>
    <div v-if="impactLoading" class="impact-empty">正在计算影响范围…</div>
    <template v-else-if="rerunBatch"><div class="batch-summary"><b>重跑批次 #{{rerunBatch.id}}</b><span :class="['runtime-pill',runtimeClass(rerunBatch.status)]"><i></i>{{runtimeLabel(rerunBatch.status)}}</span><span>{{rerunBatch.successTasks}} 成功</span><span>{{rerunBatch.failedTasks}} 失败</span><span>{{rerunBatch.waitingTasks}} 等待依赖</span></div><div class="impact-list"><div v-for="t in rerunBatch.tasks" :key="t.id" class="impact-row"><span class="seq">{{t.sequenceNo}}</span><b>{{t.name}}</b><span :class="['runtime-pill',runtimeClass(t.status)]"><i></i>{{runtimeLabel(t.status)}}</span><small>{{t.errorMessage||''}}</small></div></div></template>
    <template v-else-if="impactView"><div class="impact-summary">预计影响 <b>{{impactView.tasks.length}}</b> 个任务，按依赖顺序执行；上游失败时对应下游保持“等待依赖”。</div><div class="impact-list"><div v-for="(t,i) in impactView.tasks" :key="t.fileId" class="impact-row"><span class="seq">{{i+1}}</span><b>{{t.name}}</b><span>层级 {{t.level}}</span><span>{{lifecycleLabel(t.lifecycleStatus)}}</span></div></div></template>
    <div v-else class="impact-empty">请选择项目工作流中的任务节点。</div>
    <template #footer><button class="btn" @click="impactOpen=false">关闭</button><button v-if="impactView&&!rerunBatch" class="btn primary" :disabled="impactLoading||!impactView.tasks.length" @click="startImpactRerun">开始重跑</button></template>
  </el-dialog>
</div>
</template>

